import React from "react";

export default function UsersLayout({ children }: { children: React.ReactNode }) {
  return (
    <div className="px-6 py-8">
      <h1 className="text-4xl font-bold mb-6">User Management</h1>

      {/* Section Navigation */}
      <nav className="mb-8 flex gap-4 text-blue-600">
        <a href="/users" className="hover:underline">All Users</a>
        <a href="/users/new" className="hover:underline">Create User</a>
      </nav>

      {/* Page Content */}
      <div className="bg-white p-6 rounded-lg shadow">
        {children}
      </div>
    </div>
  );
}